I added point markers, computed hour-to-hour deltas (shown in tooltips), and placed small delta labels above each point so the hour-to-hour movement is much clearer. Below is the complete updated Vega-Lite specification.

```json
{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "values": [
      {
        "date": "Sun, 01 Jan 2012 23:00:00",
        "price": 150
      },
      {
        "date": "Sun, 02 Jan 2012 00:00:00",
        "price": 100
      },
      {
        "date": "Sun, 02 Jan 2012 01:00:00",
        "price": 170
      },
      {
        "date": "Sun, 02 Jan 2012 02:00:00",
        "price": 165
      },
      {
        "date": "Sun, 02 Jan 2012 03:00:00",
        "price": 200
      }
    ]
  },
  "transform": [
    {
      "window": [
        {
          "op": "lag",
          "as": "prev_price"
        }
      ],
      "sort": [
        {
          "field": "date",
          "order": "ascending"
        }
      ]
    },
    {
      "calculate": "datum.prev_price == null ? null : (datum.price - datum.prev_price)",
      "as": "delta"
    },
    {
      "calculate": "datum.delta == null ? '' : (datum.delta > 0 ? '+' + round(datum.delta) : '' + round(datum.delta))",
      "as": "deltaLabel"
    }
  ],
  "encoding": {
    "x": {
      "axis": {
        "labelAngle": 0
      },
      "field": "date",
      "timeUnit": "utcyearmonthdatehoursminutes",
      "type": "temporal"
    },
    "y": {
      "field": "price",
      "type": "quantitative",
      "scale": {
        "zero": false
      }
    }
  },
  "layer": [
    {
      "mark": {
        "type": "line",
        "strokeWidth": 3,
        "color": "#0b3d91"
      }
    },
    {
      "mark": {
        "type": "point",
        "filled": true,
        "size": 100,
        "color": "#0b3d91"
      },
      "encoding": {
        "tooltip": [
          {
            "field": "date",
            "type": "temporal",
            "title": "Date"
          },
          {
            "field": "price",
            "type": "quantitative",
            "title": "Price"
          },
          {
            "field": "delta",
            "type": "quantitative",
            "title": "Hour change"
          }
        ]
      }
    },
    {
      "mark": {
        "type": "text",
        "dy": -12,
        "fontSize": 11,
        "color": "#333"
      },
      "encoding": {
        "text": {
          "field": "deltaLabel",
          "type": "nominal"
        }
      }
    }
  ]
}
```
